        "questionText": "'ऑनलाइन गेमिंग की लत और हानियाँ' विषय पर दो पात्रों के मध्य लगभग 80-100 शब्दों में एक सजीव और प्रेरक संवाद लिखिए।",
        "modelAnswer": "विकास: नमस्ते कुणाल! आज तुम कक्षा में इतने सुस्त और उनींदे क्यों लग रहे हो? तुम्हारी आँखें भी लाल हैं!\nकुणाल: नमस्ते विकास! क्या बताऊं, कल रात मैं अपने मोबाइल पर एक नया ऑनलाइन बैटलग्राउंड गेम खेल रहा था और खेलते-खेलते रात के तीन कब बज गए, पता ही नहीं चला।\nविकास: कुणाल! यह बहुत खतरनाक लत है। देर रात तक स्क्रीन देखने से तुम्हारी नींद पूरी नहीं हो रही है, जिससे सिरदर्द और एकाग्रता की कमी की समस्या हो जाएगी।\nकुणाल: लेकिन गेम खेलने में इतना रोमांच आता है कि जीतने का जुनून सवार हो जाता है!\nविकास: यही जुनून जब लत बन जाता है, तो पढ़ाई, स्वास्थ्य और पारिवारिक रिश्ते सब पीछे छूट जाते हैं। कई बच्चे तो इसमें पैसे गँवाकर गंभीर अवसाद में चले जाते हैं। क्या तुम अपने वास्तविक जीवन के सपनों को इस आभासी खेल के लिए बर्बाद करना चाहते हो?\nकुणाल: तुमने मेरी आँखें खोल दीं विकास। आज ही मैं अपने फोन से इन गेम्स को अनइंस्टॉल करूँगा और शाम को तुम्हारे साथ मैदान में फुटबॉल खेलने चलूँगा।",
