        "questionText": "दिए गए प्रस्थान बिंदु के आधार पर लगभग 100-120 शब्दों में एक शिक्षाप्रद लघुकथा लिखिए तथा उपयुक्त शीर्षक व सीख भी दीजिए:\n\nप्रस्थान बिंदु: 'एक वृद्ध किसान के चार बेटे आपस में हमेशा लड़ते रहते थे। जब किसान मृत्यु-शय्या पर था, उसने चारों को बुलाया...'",
