        "modelAnswer": "संगठन में ही शक्ति है\n\nएक वृद्ध किसान के चार बेटे थे, जो दिन-रात आपस में लड़ते-झगड़ते रहते थे। किसान उन्हें समझाने का बहुत प्रयास करता, किंतु वे किसी की नहीं सुनते थे। जब किसान अपनी मृत्यु-शय्या पर पहुँचा, तो उसे अपने बेटों के भविष्य की गहरी चिंता सताने लगी। उसने अपने चारों बेटों को अपने पास बुलाया और प्रत्येक के हाथ में एक-एक पतली लकड़ी देकर कहा, 'बेटो! जरा इन लकड़ियों को तोड़कर दिखाओ।'\n\nचारों बेटों ने बड़ी आसानी से एक ही झटके में उन लकड़ियों को दो टुकड़ों में तोड़ दिया। तब किसान ने लकड़ियों का एक मजबूत गट्ठर मँगवाया, जिसमें बीस लकड़ियाँ एक साथ बंधी थीं। किसान ने कहा, 'अब इस गट्ठर को तोड़कर दिखाओ।' चारों बेटों ने बारी-बारी से अपनी पूरी ताकत लगा दी, किंतु कोई भी उस गट्ठर को हिला तक नहीं सका।\n\nतब वृद्ध किसान ने मुस्कुराते हुए कहा, 'मेरे प्यारे बेटो! जब तक तुम अकेली लकड़ी की भाँति अलग-थलग रहोगे, कोई भी शत्रु तुम्हें सरलता से तोड़कर बर्बाद कर देगा। किंतु जब तुम इस गट्ठर की भाँति एक होकर रहोगे, तो संसार की कोई भी ताकत तुम्हारा बाल भी बांका नहीं कर सकेगी।'\n\nचारों भाइयों को अपनी भूल का अहसास हो गया। उन्होंने अपने पिता के पैर छूकर सदा मिल-जुलकर रहने की शपथ ली।\n\nसीख: संगठन और एकता में ही अपार शक्ति होती है; फूट और कलह सर्वनाश का कारण बनते हैं।",
