        "modelAnswer": "परीक्षा भवन,\nनई दिल्ली।\nदिनांक: 25 फरवरी 2024\n\nसेवा में,\nश्रीमान पुलिस अधीक्षक महोदय,\nदक्षिण-पश्चिम जिला, वसंत कुंज, नई दिल्ली।\n\nविषय: वसंत कुंज एन्क्लेव क्षेत्र में बढ़ती चोरी की घटनाओं एवं रात्रि गश्त बढ़ाने के संबंध में।\n\nमहोदय,\nसविनय निवेदन है कि मैं वसंत कुंज एन्क्लेव का निवासी हूँ। मैं इस पत्र के माध्यम से अपने आवासीय क्षेत्र में विगत कुछ हफ्तों से लगातार बढ़ रही चोरी की वारदातों और असामाजिक तत्वों की संदिग्ध गतिविधियों की ओर आपका ध्यान आकृष्ट कराना चाहता हूँ।\n\nविगत दस दिनों के भीतर हमारे ब्लॉक में तीन बंद मकानों के ताले टूट चुके हैं तथा दिनदहाड़े एक महिला से सोने की चेन छीनने की घटना घटित हुई है। शाम ढलते ही मुख्य चौराहे और पार्कों के निकट आवारा और असामाजिक तत्वों का जमावड़ा लग जाता है, जिससे महिलाओं और वरिष्ठ नागरिकों का शाम को घर से निकलना असुरक्षित हो गया है। स्थानीय पुलिस चौकी में शिकायत करने पर भी कोई ठोस कदम नहीं उठाया गया है।\n\nअतः आपसे करबद्ध प्रार्थना है कि क्षेत्र में नागरिकों की जान-माल की सुरक्षा सुनिश्चित करने हेतु रात्रि के समय पीसीआर वैन की नियमित गश्त बढ़वाई जाए और संदिग्ध व्यक्तियों की जांच की जाए।\n\nसधन्यवाद।\n\nभवदीय,\nप्रणव मेहता\n(सचिव, नागरिक सुरक्षा समिति)",
